package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CountingOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarArchiveOutputStream.write
 */
public class TarArchiveOutputStream_write_TriageGen1Test {

    private ByteArrayOutputStream baos;
    private TarArchiveOutputStream tarStream;
    private static final int RECORD_SIZE = 512;

    @Before
    public void setUp() throws IOException {
        baos = new ByteArrayOutputStream();
        // Using a fixed record size for predictable testing
        tarStream = new TarArchiveOutputStream(baos, RECORD_SIZE, RECORD_SIZE);
    }

    @Test
    public void testWrite_ExceedsSizeInHeader() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        // Manually setting a small size to trigger the IOException
        // Note: In a real scenario, the size is set via the entry
        tarStream.putArchiveEntry(entry);

        // We need to simulate the internal state where currSize is small.
        // Since we can't easily set currSize via public API without knowing internal implementation,
        // we rely on the fact that if we try to write more than the entry size, it throws.
        byte[] data = new byte[100];
        // If the entry size was 0 (default), writing 100 should fail.
        try {
            tarStream.write(data, 0, 100);
            Assert.fail("Should have thrown IOException due to size mismatch");
        } catch (IOException e) {
            Assert.assertTrue(e.getMessage().contains("exceeds size in header"));
        }
    }

    @Test
    public void testWrite_AssembleBufferPartial() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(RECORD_SIZE);
        tarStream.putArchiveEntry(entry);

        byte[] data = new byte[RECORD_SIZE];
        for (int i = 0; i < RECORD_SIZE; i++) data[i] = (byte) (i % 128);

        // Scenario: Write half a record (triggers assemLen > 0 logic)
        int half = RECORD_SIZE / 2;
        tarStream.write(data, 0, half);

        // Verify nothing written to underlying stream yet because it's in assemBuf
        Assert.assertEquals(0, baos.size());

        // Scenario: Write the second half (triggers (assemLen + numToWrite) >= recordBuf.length)
        tarStream.write(data, half, half);

        Assert.assertEquals(RECORD_SIZE, baos.size());
        Assert.assertArrayEquals(data, baos.toByteArray());
    }

    @Test
    public void testWrite_AssembleBufferOverflowToRecord() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(RECORD_SIZE * 2);
        tarStream.putArchiveEntry(entry);

        byte[] data = new byte[RECORD_SIZE * 2];
        for (int i = 0; i < data.length; i++) data[i] = (byte) (i % 128);

        // 1. Fill assemBuf partially
        tarStream.write(data, 0, 100);

        // 2. Write enough to trigger the "if ((assemLen + numToWrite) >= recordBuf.length)" block
        // We need 512 - 100 = 412 more bytes to complete the record
        tarStream.write(data, 100, 412);

        Assert.assertEquals(RECORD_SIZE, baos.size());

        // 3. Write remaining bytes (this will go into the while(numToWrite > 0) loop)
        // Remaining is 1024 - 512 = 512. 
        // This should trigger the buffer.writeRecord(wBuf, wOffset) inside the while loop
        tarStream.write(data, 512, 512);

        Assert.assertEquals(RECORD_SIZE * 2, baos.size());
    }

    @Test
    public void testWrite_DirectWriteLargeBuffer() throws IOException {
        int totalSize = RECORD_SIZE * 3;
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(totalSize);
        tarStream.putArchiveEntry(entry);

        byte[] data = new byte[totalSize];
        for (int i = 0; i < totalSize; i++) data[i] = (byte) (i % 128);

        // Write exactly 3 records at once. 
        // This should skip the assemLen > 0 block (since assemLen starts at 0)
        // and enter the while(numToWrite > 0) loop.
        tarStream.write(data, 0, totalSize);

        Assert.assertEquals(totalSize, baos.size());
        Assert.assertArrayEquals(data, baos.toByteArray());
    }

    @Test
    public void testWrite_SmallWritesToAssemble() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(RECORD_SIZE);
        tarStream.putArchiveEntry(entry);

        byte[] data = new byte[RECORD_SIZE];
        for (int i = 0; i < RECORD_SIZE; i++) data[i] = (byte) (i % 128);

        // Write in many tiny chunks
        int chunkSize = 10;
        for (int i = 0; i < RECORD_SIZE; i += chunkSize) {
            tarStream.write(data, i, chunkSize);
        }

        Assert.assertEquals(RECORD_SIZE, baos.size());
        Assert.assertArrayEquals(data, baos.toByteArray());
    }

    @Test
    public void testWrite_WriteZeroBytes() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(RECORD_SIZE);
        tarStream.putArchiveEntry(entry);

        byte[] data = new byte[10];
        // Writing 0 bytes should not throw and not change anything
        tarStream.write(data, 0, 0);

        Assert.assertEquals(0, baos.size());
    }
}
